""" """

import os
import unittest

import bioblend
from bioblend.galaxy import GalaxyInstance
from . import (
    GalaxyTestBase,
    test_util,
)

# Minimal user-tool representation (mirrors TOOL_WITH_SHELL_COMMAND from
# galaxy_test.base.populators). Running the tool requires a container
# runtime (busybox); the run test is gated on that.
USER_TOOL_REPRESENTATION = {
    "id": "bioblend_test_basecommand",
    "name": "BioBlend test base command tool",
    "class": "GalaxyUserTool",
    "container": "busybox",
    "version": "1.0.0",
    "shell_command": "cat '$(inputs.input.path)' > output.txt",
    "inputs": [
        {
            "type": "data",
            "name": "input",
            "format": "txt",
        }
    ],
    "outputs": [
        {
            "type": "data",
            "from_work_dir": "output.txt",
            "name": "output",
        }
    ],
}


@test_util.skip_unless_galaxy("release_25.0")
class TestGalaxyUnprivilegedTools(GalaxyTestBase.GalaxyTestBase):
    admin_gi: GalaxyInstance
    role_id: str

    @classmethod
    def setUpClass(cls):
        super().setUpClass()
        master_key = os.environ.get("BIOBLEND_GALAXY_MASTER_API_KEY")
        if not master_key:
            raise unittest.SkipTest(
                "BIOBLEND_GALAXY_MASTER_API_KEY is required to grant the test user the user_tool_execute role."
            )
        cls.admin_gi = GalaxyInstance(url=os.environ["BIOBLEND_GALAXY_URL"], key=master_key)
        user_id = cls.gi.users.get_current_user()["id"]
        payload = {
            "name": f"bioblend_user_tool_execute_{user_id}",
            "description": "BioBlend test role granting user_tool_execute",
            "role_type": "user_tool_execute",
            "user_ids": [user_id],
            "group_ids": [],
        }
        role = cls.admin_gi.make_post_request(f"{cls.admin_gi.url}/roles", payload=payload)
        cls.role_id = role["id"]

    @classmethod
    def tearDownClass(cls):
        role_id = getattr(cls, "role_id", None)
        if role_id:
            try:
                cls.admin_gi.make_delete_request(f"{cls.admin_gi.url}/roles/{role_id}")
                cls.admin_gi.make_post_request(f"{cls.admin_gi.url}/roles/{role_id}/purge", payload={})
            except bioblend.ConnectionError:
                pass

    def setUp(self):
        super().setUp()
        try:
            created = self.gi.unprivileged_tools.create_user_tool(USER_TOOL_REPRESENTATION)
        except bioblend.ConnectionError as e:
            # Galaxy refuses dynamic tool creation unless enable_beta_tool_formats
            "elapsed_seconds": elapsed_seconds,
            "evidence_directory": evidence_directory,
            "failure_summary": failure_summary,
            "history_mismatch": history_mismatch,
            "inline_outputs": inline_outputs,
            "jobs": wait_result["jobs"],
            "output_collection_refs": output_collection_refs,
            "output_collection_verification": collection_verification,
            "output_dataset_refs": output_refs,
            "output_verification": output_verification,
            "parameter_provenance": parameter_provenance,
            "provenance": provenance,
            "selected_input_format": selected_input_format,
            "status": status,
            "submitted": True,
            "tool_id": tool_id,
            "validation_status": validation_status,
        },
        secrets,
    )
    _write_json(evidence_path / "summary.json", summary)
    return summary


def _validate_udt_representation(representation: Mapping[str, Any]) -> dict[str, Any]:
    exact = dict(representation)
    if exact.get("class") != "GalaxyUserTool":
        raise ValueError("UDT representation class must be 'GalaxyUserTool'")
    for field in ("id", "name", "version", "shell_command"):
        if not isinstance(exact.get(field), str) or not exact[field].strip():
            raise ValueError(f"UDT representation requires non-empty {field!r}")
    for field in ("inputs", "outputs"):
        if not isinstance(exact.get(field), list) or not exact[field]:
            raise ValueError(f"UDT representation requires a non-empty {field!r} list")
    return exact


def _resolve_quay_container_digest(
    container: str,
    *,
    request_get: Callable[..., Any] | None = None,
) -> dict[str, Any]:
    """Resolve a public Quay tag to registry and Linux/AMD64 manifest digests."""

    reference = str(container).strip()
    record: dict[str, Any] = {"container": reference, "registry": "quay.io"}
    if reference.startswith("docker://") or "@sha256:" in reference:
        return {**record, "status": "invalid_reference"}
    match = re.fullmatch(r"quay\.io/([^:]+):([^/:]+)", reference)
    if match is None:
        return {**record, "status": "unsupported_or_untagged_reference"}
    repository, tag = match.groups()
    record.update({"repository": repository, "tag": tag})

    if request_get is None:
        import requests

        request_get = requests.get

    accept = ", ".join(
        (
            "application/vnd.oci.image.index.v1+json",
            "application/vnd.docker.distribution.manifest.list.v2+json",
            "application/vnd.oci.image.manifest.v1+json",
            "application/vnd.docker.distribution.manifest.v2+json",
        )
    )
    manifest_url = f"https://quay.io/v2/{repository}/manifests/{tag}"
    headers = {"Accept": accept}
    response = request_get(manifest_url, headers=headers, timeout=30)
    if response.status_code == 401:
        challenge = str(response.headers.get("WWW-Authenticate") or "")
        if not challenge.lower().startswith("bearer "):
            return {**record, "status": "registry_auth_unavailable"}
        params = dict(re.findall(r'(\w+)="([^"]*)"', challenge))
        realm = params.pop("realm", "")
        if not realm:
            return {**record, "status": "registry_auth_unavailable"}
        params.setdefault("scope", f"repository:{repository}:pull")
        token_response = request_get(realm, params=params, timeout=30)
        token_response.raise_for_status()
        token_payload = token_response.json()
        token = token_payload.get("token") or token_payload.get("access_token")
        if not token:
            return {**record, "status": "registry_auth_unavailable"}
        response = request_get(
            manifest_url,
            headers={"Accept": accept, "Authorization": f"Bearer {token}"},
            timeout=30,
        )
    response.raise_for_status()

